/**
 * Single source of truth for pricing across JSX, JSON-LD, llms.txt, the OSS
 * README, and the OG image generator.
 *
 * `BASE_PRICING` is the authoritative INR price (Razorpay processes in INR).
 * `CURRENCIES` is presentation-only — what we display when the visitor's
 * region is detected. Updating BASE_PRICING here flows through to:
 *   - <Pricing /> page comparison cards
 *   - JSON-LD Service / Offer schemas
 *   - SoftwareApplication offers in index.html
 *   - llms.txt (regenerated by scripts/generate-llms.ts)
 *   - sitemap.xml (regenerated by scripts/generate-sitemap.ts)
 */

export type PlanKey = 'oss' | 'pro' | 'enterprise';

export interface Plan {
  key: PlanKey;
  name: string;
  /** INR per month. 0 = free / self-host. */
  inrPerMonth: number;
  /** One-line value-prop used in JSON-LD `description`. */
  shortDescription: string;
  /** URL the offer points at (deeplink, signup, GitHub releases, mailto). */
  offerUrl: string;
  /** Bullet features in display order. */
  features: string[];
}

