/**
 * Display-only currency conversions for the regional selector.
 * Razorpay processes the INR value above. Keep this list in sync with the UI
 * dropdown — do not let the numbers drift apart from the multiplier each
 * currency implies, since visitors will compare them.
 */
export interface CurrencyDisplay {
  code: string;
  symbol: string;
  flag: string;
  /** Display price for the Pro plan in this currency. */
  pro: number;
  /** Display price for the Enterprise plan in this currency. */
  enterprise: number;
}

export const CURRENCIES: CurrencyDisplay[] = [
  { code: 'USD', symbol: '$', flag: '🇺🇸', pro: 1, enterprise: 24 },
  { code: 'EUR', symbol: '€', flag: '🇪🇺', pro: 1, enterprise: 22 },
  { code: 'GBP', symbol: '£', flag: '🇬🇧', pro: 1, enterprise: 19 },
  { code: 'INR', symbol: '₹', flag: '🇮🇳', pro: 100, enterprise: 2000 },
  { code: 'CAD', symbol: 'C$', flag: '🇨🇦', pro: 2, enterprise: 33 },
  { code: 'AUD', symbol: 'A$', flag: '🇦🇺', pro: 2, enterprise: 36 },
  { code: 'JPY', symbol: '¥', flag: '🇯🇵', pro: 175, enterprise: 3500 },
  { code: 'BRL', symbol: 'R$', flag: '🇧🇷', pro: 6, enterprise: 118 },
];

export function formatPriceLabel(plan: Plan): string {
  if (plan.inrPerMonth === 0) return 'Free';
  return `₹${plan.inrPerMonth.toLocaleString()}`;
}
